 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []

    # Locate solid 2x2 markers and their four diagonal corner colors.
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                corners = [(r - 1, c - 1), (r - 1, c + 2), (r + 2, c - 1), (r + 2, c + 2)]
                if all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0 for rr, cc in corners):
                    blocks.append(corners)

    # Each outward diagonal ray takes the color from the preceding corner
    # in the cycle NW <- SW <- SE <- NE <- NW.
    for nw, ne, sw, se in blocks:
        rays = [(nw, grid[sw[0]][sw[1]], -1, -1),
                (ne, grid[nw[0]][nw[1]], -1, 1),
                (sw, grid[se[0]][se[1]], 1, -1),
                (se, grid[ne[0]][ne[1]], 1, 1)]
        for (r, c), color, dr, dc in rays:
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out
